-- p4 apply body, copied unchanged from 04-difficulty-duplicates/apply.sql.
DO $do$ DECLARE n int; BEGIN
UPDATE "QuestionBankItem" q SET difficulty=p.new_d, "updatedAt"=now()
FROM jsonb_to_recordset($pl$[{"id":"cmr7sbvmg00181y2vsbjypz8k","old_d":4,"new_d":3},{"id":"cmr0mle46000q1y3490phnae0","old_d":2,"new_d":3},{"id":"cmshjhax4000e1yspzhhgi60e","old_d":4,"new_d":2},{"id":"cmshi6sg3000w1y29myjdx6d8","old_d":4,"new_d":3},{"id":"cmros03zl001x1yok8cg1xwed","old_d":4,"new_d":3},{"id":"cmr0mwumu005u1y34d17ywgi8","old_d":5,"new_d":4},{"id":"cmr4j6rb3001j1ygk3d8iub8e","old_d":4,"new_d":3},{"id":"cmrorqphl00041yokjywzmgz7","old_d":4,"new_d":3},{"id":"cmsfjapv400081yms128u5ldf","old_d":4,"new_d":2},{"id":"cmr80qoix001j1yjnfiqt6uv4","old_d":4,"new_d":3},{"id":"cmr4fwi6x004a1yroyencxdt1","old_d":5,"new_d":4},{"id":"cmshg6q0i001y1yft25u0888l","old_d":3,"new_d":2},{"id":"cmr4edxdz003t1yk37bjn2ajl","old_d":4,"new_d":3},{"id":"cmrovuyoo000c1yu3xnnykipd","old_d":3,"new_d":2},{"id":"cmr7ugsow00151yt3cpldkcqn","old_d":2,"new_d":3},{"id":"cmra6ltbk000k1ybjys03owcn","old_d":5,"new_d":2},{"id":"cmr4itdnw004f1y7u7to1kbt1","old_d":2,"new_d":3}]$pl$::jsonb) AS p(id text, old_d int, new_d int)
WHERE q.id=p.id AND q."fieldId"='pharmacy' AND q.difficulty=p.old_d;
GET DIAGNOSTICS n = ROW_COUNT;
IF n <> 17 THEN RAISE EXCEPTION 'P4-A difficulty: expected 17 rows, got %', n; END IF;
END $do$;

